args.query:
WITH data AS (
    SELECT 
        SUM(1) as total,
        json_group_array(
            '{session_id":"'||session_id||'","participant_id":"'||participant_id||'","condition":"'||condition||'","cognitive_score":'||cognitive_score||',"reaction_ms":'||reaction_ms||',"recorded_at":"'||recorded_at||'","status":"'||status||'","notes":"'||replace(replace(replace(notes, '"', '""'), "\\", '\\'), '''', '|CHAIN|')||'"}'
        ) as mj
    FROM measurements WHERE DATE(recorded_at) = '2026-11-03'
)
SELECT json_group_array(m), mj, total FROM data;

WITH base AS (
  SELECT row_number() OVER () as rn FROM measurements WHERE DATE(recorded_at) = '2026-11-03'
), 
all_rows AS (
  SELECT m.*, r.rn FROM measurements m JOIN base r ON m.session_id = (SELECT session_id FROM measurements WHERE row_number() OVER () = r.rn AND DATE(recorded_at) = '2026-11-03')
)
SELECT * FROM all_rows LIMIT 3;
